from pathlib import Path
from pynwb import NWBHDF5IO
import numpy as np
path=sorted(Path('/app/data').glob('sub-*/*.nwb'))[0]
with NWBHDF5IO(str(path), 'r', load_namespaces=True) as io:
    nwb=io.read()
    trials=nwb.trials.to_dataframe()
    go=nwb.acquisition['BehavioralEvents']['go_start_times'].timestamps[:]
    left=nwb.acquisition['BehavioralEvents']['left_lick_times'].timestamps[:]
    right=nwb.acquisition['BehavioralEvents']['right_lick_times'].timestamps[:]
    # summarize first post-go lick side for each outcome among no-early trials
    summary={}
    for idx,row in trials.iterrows():
        st,en=row['start_time'],row['stop_time']
        g=go[idx]
        post=[]
        for t in left[(left>=st)&(left<=en)]:
            if t>=g: post.append((t-g,0))
        for t in right[(right>=st)&(right<=en)]:
            if t>=g: post.append((t-g,1))
        post.sort()
        first=post[0][1] if post else None
        summary.setdefault((str(row['early_lick']),str(row['outcome'])), {0:0,1:0,None:0})
        summary[(str(row['early_lick']),str(row['outcome']))][first]+=1
    for k,v in summary.items():
        print(k,v)
