from pathlib import Path
import h5py, numpy as np

def dec(arr):
    out=[]
    for v in arr:
        if isinstance(v,(bytes,bytearray)): out.append(v.decode())
        elif hasattr(v,'decode'): out.append(v.decode())
        else: out.append(str(v))
    return np.asarray(out)

def parse(arr):
    out=[]
    for v in arr:
        if isinstance(v,(bytes,bytearray)): v=v.decode()
        elif hasattr(v,'decode'): v=v.decode()
        else: v=str(v)
        out.append(np.nan if v in {'N/A','nan','NaN',''} else float(v))
    return np.asarray(out,float)

all_sessions=0
stim_sessions=0
stim_subjects=set()
raw_counts=[]
for path in sorted(Path('/app/data').glob('sub-*/*.nwb')):
    with h5py.File(path,'r') as f:
        units=f['units']
        good=(dec(units['classification'][()])=='good')
        if good.sum()==0:
            continue
        all_sessions+=1
        n_ephys=units['is_good_trials'].shape[1]
        raw_counts.append(n_ephys)
        tr=f['intervals/trials']
        stim_power=parse(tr['photostim_power'][()])[:n_ephys]
        if np.any(np.isfinite(stim_power) & (stim_power>0)):
            stim_sessions+=1
            stim_subjects.add(path.parent.name.replace('sub-',''))
print('included_sessions', all_sessions)
print('raw_trials_mean', float(np.mean(raw_counts)))
print('raw_trials_min', int(np.min(raw_counts)))
print('raw_trials_max', int(np.max(raw_counts)))
print('stim_sessions', stim_sessions)
print('stim_subjects', len(stim_subjects), sorted(stim_subjects))
